// Generated by progression/tools/capstones.py: Mastery Crown recipe, decree recipes, old-capstone right-click (ages open by bosses: progression_boss_gates.js).
ServerEvents.recipes(event => {
  event.custom({"type":"minecraft:crafting_shapeless","ingredients":[{"item":"draconicevolution:awakened_core"},{"item":"botania:mana_resource","meta":5,"type":"botania:stack"},{"item":"draconicevolution:chaos_shard"},{"item":"minecraft:paper"}],"result":{"id":"kubejs:mastery_crown","count":1}}).id("progression:capstone/mastery_crown")
  // Bountiful decrees (optional side jobs, never a gate): handed out when an age opens (progression_boss_gates.js); copies from paper
  if (Item.exists("bountiful:decree_settler")) event.shapeless("bountiful:decree_settler", ["kubejs:settlers_charter", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:settlers_charter").id("progression:decree/settler")
  if (Item.exists("bountiful:decree_settler")) event.shapeless("bountiful:decree_settler", ["bountiful:decree_settler", "minecraft:paper"]).keepIngredient("bountiful:decree_settler").id("progression:decree/settler_copy")
  if (Item.exists("bountiful:decree_settler") && Item.exists("bountiful:bountyboarditem")) event.shaped("bountiful:decree_settler", ["IFI", "PBP", " G "], {I: "minecraft:ink_sac", F: "minecraft:feather", P: "minecraft:paper", B: "bountiful:bountyboarditem", G: "minecraft:gold_nugget"}).keepIngredient("bountiful:bountyboarditem").id("progression:decree/settler_new")
  if (Item.exists("bountiful:decree_homestead")) event.shapeless("bountiful:decree_homestead", ["kubejs:homestead_seal", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:homestead_seal").id("progression:decree/homestead")
  if (Item.exists("bountiful:decree_homestead")) event.shapeless("bountiful:decree_homestead", ["bountiful:decree_homestead", "minecraft:paper"]).keepIngredient("bountiful:decree_homestead").id("progression:decree/homestead_copy")
  if (Item.exists("bountiful:decree_engineer")) event.shapeless("bountiful:decree_engineer", ["kubejs:engineers_compact", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:engineers_compact").id("progression:decree/engineer")
  if (Item.exists("bountiful:decree_engineer")) event.shapeless("bountiful:decree_engineer", ["bountiful:decree_engineer", "minecraft:paper"]).keepIngredient("bountiful:decree_engineer").id("progression:decree/engineer_copy")
  if (Item.exists("bountiful:decree_nether")) event.shapeless("bountiful:decree_nether", ["kubejs:nether_accord", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:nether_accord").id("progression:decree/nether")
  if (Item.exists("bountiful:decree_nether")) event.shapeless("bountiful:decree_nether", ["bountiful:decree_nether", "minecraft:paper"]).keepIngredient("bountiful:decree_nether").id("progression:decree/nether_copy")
  if (Item.exists("bountiful:decree_realm")) event.shapeless("bountiful:decree_realm", ["kubejs:realm_key", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:realm_key").id("progression:decree/realm")
  if (Item.exists("bountiful:decree_realm")) event.shapeless("bountiful:decree_realm", ["bountiful:decree_realm", "minecraft:paper"]).keepIngredient("bountiful:decree_realm").id("progression:decree/realm_copy")
  if (Item.exists("bountiful:decree_mastery")) event.shapeless("bountiful:decree_mastery", ["kubejs:mastery_crown", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:mastery_crown").id("progression:decree/mastery")
  if (Item.exists("bountiful:decree_mastery")) event.shapeless("bountiful:decree_mastery", ["bountiful:decree_mastery", "minecraft:paper"]).keepIngredient("bountiful:decree_mastery").id("progression:decree/mastery_copy")
})

const CAPSTONES = {
  "kubejs:settlers_charter": { age: 1, name: "Settler's Charter", next: "Age 2: Homestead" },
  "kubejs:homestead_seal": { age: 2, name: "Homestead Seal", next: "Age 3: Iron & Tinkering" },
  "kubejs:engineers_compact": { age: 3, name: "Engineer's Compact", next: "Age 4: Nether & Power" },
  "kubejs:nether_accord": { age: 4, name: "Nether Accord", next: "Age 5: New Worlds" },
  "kubejs:realm_key": { age: 5, name: "Realm Key", next: "Age 6: Mastery" },
  "kubejs:mastery_crown": { age: 6, name: "Mastery Crown", next: "the end of the guide" },
}

ItemEvents.rightClicked(event => {
  const id = String(event.item.id)
  const cap = CAPSTONES[id]
  if (!cap || event.hand != "main_hand") return
  const player = event.player
  if (cap.age < 6) player.tell(Text.gray(cap.name + " is a keepsake now: ages open by defeating bosses (/sf3ages). It still makes its Bounty decree."))
  if (player.persistentData.getBoolean("progression_reward_" + cap.age)) { player.tell(Text.gold(cap.name + ": this reward was already paid.")); return }
  player.persistentData.putBoolean("progression_reward_" + cap.age, true)
  event.server.runCommandSilent("loot give " + player.username + " loot progression:rewards/age_" + cap.age)
  event.server.runCommandSilent("loot give " + player.username + " loot progression:rewards/hint_" + cap.age)
  player.tell(Text.gold(cap.name + " rewards you."))
  event.server.runCommandSilent("playsound minecraft:ui.toast.challenge_complete master " + player.username)
})
